<template><ion-page><ion-header><ion-toolbar><ion-title class="toolbar-brand-right">Task<span>Edu</span></ion-title></ion-toolbar></ion-header><ion-content><main class="page-container"><header class="page-heading actions"><div><p>{{paginaAtividades?"GESTÃO DE ATIVIDADES":"RESUMO DO PROFESSOR"}}</p><h1>{{saudacao()}}, Prof. {{primeiroNome}} 👋</h1><span class="hero-support">{{paginaAtividades?"Busque, filtre e gerencie suas publicações.":"Acompanhe suas turmas e os próximos prazos."}}</span></div><ion-button router-link="/professor/nova-atividade"><ion-icon slot="start" :icon="addOutline"/>Nova atividade</ion-button></header><section v-if="!paginaAtividades" class="metric-grid"><article><span>Publicadas</span><strong>{{atividades.length}}</strong><small>no total</small></article><article><span>Esta semana</span><strong>{{semana}}</strong><small>próximos 7 dias</small></article><article><span>Turmas</span><strong>{{turmas}}</strong><small>atendidas</small></article><article><span>Próximas</span><strong>{{proximas}}</strong><small>prazos futuros</small></article></section><template v-if="paginaAtividades"><div class="section-title"><div><p class="section-kicker">GESTÃO DE CONTEÚDO</p><h2>{{paginaAtividades?"Todas as publicações":"Próximos 3 prazos"}}</h2></div><p v-if="paginaAtividades">{{filtradas.length}} resultado(s)</p><router-link v-else to="/professor/atividades">Ver todas as atividades →</router-link></div><div v-if="paginaAtividades" class="filters-panel teacher-filters"><ion-searchbar v-model="busca" placeholder="Buscar título ou matéria" :debounce="200"/><ion-select v-model="turma" label="Turma" label-placement="stacked" fill="outline"><ion-select-option value="">Todas</ion-select-option><ion-select-option v-for="item in opcoesTurma" :key="item" :value="item">{{item}}</ion-select-option></ion-select><ion-select v-model="tipo" label="Tipo" label-placement="stacked" fill="outline"><ion-select-option value="">Todos</ion-select-option><ion-select-option v-for="item in TIPOS_ATIVIDADE" :key="item" :value="item">{{item}}</ion-select-option></ion-select><ion-select v-model="ordem" label="Ordenar" label-placement="stacked" fill="outline"><ion-select-option value="asc">Mais próximas</ion-select-option><ion-select-option value="desc">Mais distantes</ion-select-option></ion-select></div><LoadingGrid v-if="carregando"/><div v-else class="activity-grid"><div v-if="!atividadesExibidas.length" class="empty-state full-width"><ion-icon :icon="documentsOutline"/><h3>Comece organizando sua turma</h3><p>{{paginaAtividades?"Nenhuma atividade encontrada.":"Nenhuma publicação com prazo futuro."}}</p><ion-button router-link="/professor/nova-atividade"><ion-icon slot="start" :icon="addOutline"/>Criar primeira atividade</ion-button></div><AtividadeCard v-for="item in atividadesExibidas" :key="item.id" :atividade="item" :pode-editar="paginaAtividades" :pode-excluir="paginaAtividades" @excluir="confirmarExclusao"/></div></template></main></ion-content><BottomNav tipo="professor"/></ion-page></template>
<script setup lang="ts">import { computed,ref } from 'vue';import { onIonViewWillEnter,alertController,IonButton,IonContent,IonHeader,IonIcon,IonPage,IonSearchbar,IonSelect,IonSelectOption,IonTitle,IonToolbar,toastController } from '@ionic/vue';import { addOutline,documentsOutline } from 'ionicons/icons';import AtividadeCard from '../components/AtividadeCard.vue';import BottomNav from '../components/BottomNav.vue';import LoadingGrid from '../components/LoadingGrid.vue';import { getUsuarioAtual } from '../services/auth.service';import { excluirAtividade,listarAtividadesPorProfessor } from '../services/atividades.service';import { TIPOS_ATIVIDADE,type Atividade } from '../types';import { diferencaDias,estaSemana,saudacao } from '../utils/datas';const props=defineProps<{paginaAtividades?:boolean}>();const usuario=getUsuarioAtual(),atividades=ref<Atividade[]>([]),carregando=ref(true),busca=ref(''),turma=ref(''),tipo=ref(''),ordem=ref('asc');const primeiroNome=computed(()=>usuario.value?.nome.split(' ')[0]||'Professor');const semana=computed(()=>atividades.value.filter(a=>estaSemana(a.dataEntrega.toDate())).length);const turmas=computed(()=>new Set(atividades.value.map(a=>a.turma)).size);const proximas=computed(()=>atividades.value.filter(a=>diferencaDias(a.dataEntrega.toDate())>=0).length);const opcoesTurma=computed(()=>[...new Set(atividades.value.map(a=>a.turma))]);const filtradas=computed(()=>atividades.value.filter(a=>`${a.titulo||''} ${a.materia} ${a.descricao}`.toLowerCase().includes(busca.value.toLowerCase())&&(!turma.value||a.turma===turma.value)&&(!tipo.value||a.tipo===tipo.value)).sort((a,b)=>(a.dataEntrega.toMillis()-b.dataEntrega.toMillis())*(ordem.value==='asc'?1:-1)));const atividadesExibidas=computed(()=>props.paginaAtividades?filtradas.value:atividades.value.filter(a=>diferencaDias(a.dataEntrega.toDate())>=0).sort((a,b)=>a.dataEntrega.toMillis()-b.dataEntrega.toMillis()).slice(0,3));async function carregar(){if(usuario.value)atividades.value=await listarAtividadesPorProfessor(usuario.value.uid);carregando.value=false}onIonViewWillEnter(carregar);async function confirmarExclusao(id:string){const alerta=await alertController.create({header:'Excluir atividade?',message:'Tem certeza? Esta ação não poderá ser desfeita.',buttons:['Cancelar',{text:'Excluir',role:'destructive',handler:async()=>{await excluirAtividade(id);atividades.value=atividades.value.filter(a=>a.id!==id);const toast=await toastController.create({message:'Atividade excluída.',duration:1400,color:'success',position:'top'});await toast.present()}}]});await alerta.present()}</script>
